{
  "name": "@uniswap/extended-token-list",
  "version": "2.0.0",
  "description": "◦ The Uniswap extended token list",
  "main": "build/uniswap-extended.tokenlist.json",
  "scripts": {
    "test": "mocha",
    "build": "rimraf build && mkdir -p build && node src/write.js > build/uniswap-extended.tokenlist.json",
    "prepublishOnly": "npm test && npm run build"
  },
  "files": [
    "build/uniswap-extended.tokenlist.json"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Uniswap/extended-token-list.git"
  },
  "keywords": [
    "uniswap",
    "extended",
    "token",
    "list"
  ],
  "author": "Matteen Mobasheran",
  "license": "GPL-3.0-or-later",
  "bugs": {
    "url": "https://github.com/Uniswap/extended-token-list/issues"
  },
  "homepage": "https://github.com/Uniswap/extended-token-list#readme",
  "devDependencies": {
    "@ethersproject/address": "^5.0.2",
    "@uniswap/token-list-bridge-utils": "^1.0.8",
    "@uniswap/token-lists": "^1.0.0-beta.29",
    "@uniswap/default-token-list": "*6.0.0",
    "ajv": "^6.12.3",
    "chai": "^4.2.0",
    "mocha": "^8.0.1",
    "rimraf": "^3.0.2"
  }
}

const packageJson = require('../package.json');
const schema = require('@uniswap/token-lists/src/tokenlist.schema.json');
const { expect } = require('chai');
const { getAddress } = require('@ethersproject/address');
const Ajv = require('ajv');
const buildList = require('../src/buildList');

const ajv = new Ajv({ allErrors: true, format: 'full' });
const validator = ajv.compile(schema);
let defaultTokenList;

before(async function () {
  this.timeout(150000);
  defaultTokenList = await buildList();
});

describe('buildList', () => {

  it('validates', () => {
    expect(validator(defaultTokenList)).to.equal(true);
  });

  it('contains no duplicate addresses', () => {
    const map = {};
    for (let token of defaultTokenList.tokens) {
      const key = `${token.chainId}-${token.address}`;
      expect(typeof map[key])
        .to.equal('undefined');
      map[key] = true;
    }
  });

  it('contains no duplicate symbols', () => {
    // manual override to approve certain tokens with duplicate symbols
    const approvedDuplicateSymbols = ["ust", 'alpha', 'boba', 'cvc', 'flx', 'imx', 'tru'];

    const map = {};
    for (let token of defaultTokenList.tokens) {
      let symbol = token.symbol.toLowerCase();
      if (approvedDuplicateSymbols.includes(symbol)) {
        continue;
      } else {
        const key = `${token.chainId}-${symbol}`;
        expect(typeof map[key])
          .to.equal('undefined', `duplicate symbol: ${symbol}`);
        map[key] = true;
      }
    }
  })

  it('contains no duplicate names', () => {
    const map = {};
    for (let token of defaultTokenList.tokens) {
      const key = `${token.chainId}-${token.name.toLowerCase()}`;
      expect(typeof map[key])
        .to.equal('undefined', `duplicate name: ${token.name}`);
      map[key] = true;
    }
  })

  it('all addresses are valid and checksummed', () => {
    for (let token of defaultTokenList.tokens) {
      expect(getAddress(token.address)).to.eq(token.address);
    }
  });

  it('version matches package.json', () => {
    expect(packageJson.version).to.match(/^\d+\.\d+\.\d+$/);
    expect(packageJson.version).to.equal(`${defaultTokenList.version.major}.${defaultTokenList.version.minor}.${defaultTokenList.version.patch}`);
  });
});

const { version } = require("../package.json");
const mainnet = require("./tokens/mainnet.json");
const bridgeUtils = require('@uniswap/token-list-bridge-utils');
const defaultList = require('@uniswap/default-token-list/build/uniswap-default.tokenlist.json');

module.exports = async function buildList() {
  const parsed = version.split(".");

  // build l1 extended list (without L2 data and default list entries)
  const l1ExtendedList = {
    name: "Uniswap Labs Extended",
    timestamp: new Date().toISOString(),
    version: {
      major: +parsed[0],
      minor: +parsed[1],
      patch: +parsed[2],
    },
    tags: {},
    logoURI: "ipfs://QmNa8mQkrNKp1WEEeGjFezDmDeodkWRevGFN8JCV7b4Xir",
    keywords: ["uniswap", "extended"],
    tokens: [...mainnet]
      // sort them by symbol for easy readability
      .sort((t1, t2) => {
        if (t1.chainId === t2.chainId) {
          return t1.symbol.toLowerCase() < t2.symbol.toLowerCase() ? -1 : 1;
        }
        return t1.chainId < t2.chainId ? -1 : 1;
      }),
  };

  // add L2 data
  const multichainExtendedList = await bridgeUtils.chainify(l1ExtendedList);

  // add default list entries (resolves conflicts to default list)
  const mergedExtendedList = bridgeUtils.mergeTokenLists(
    defaultList,
    multichainExtendedList);

  // maintain original non-tokens properties of extended list (name, version, timestamp, etc) since mergeTokenLists overwrites them
  const finalExtendedList = {
    ...l1ExtendedList,
    tokens: mergedExtendedList.tokens
  };

    return finalExtendedList;
};
